contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 value) public {
        // setup: as owner, mint `value` so this contract's balance is at least `value`
        c.mintToken(address(this), value); if (__ESBMC_reverted()) return;
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.burn(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint256 balAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 supplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;
        assert(!reverted && balAfter + value == balBefore && supplyAfter + value == supplyBefore);
    }
    receive() external payable {}
}

