pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 value) internal {
        try c.mintToken(address(this), value) {} catch { return; }
        uint256 balBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        bool reverted;
        try c.burn(value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balAfter;
        try c.balanceOf(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint256 supplyAfter;
        try c.totalSupply() returns (uint256 __r) { supplyAfter = __r; } catch { return; }
        assertTrue(!reverted && balAfter + value == balBefore && supplyAfter + value == supplyBefore);
    }

    function testFuzz_run(uint256 value) public {
        _run(value);
    }

    receive() external payable {}
}
